LB_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPORT_DIR="$LB_ROOT/docs/field"
REPO_URL="https://github.com/s-ictokuyama-glitch/LinguaBridge"

field_verification_preflight() {
  local python_bin=""
  if [[ ! -f "$LB_ROOT/requirements-bench.txt" ]]; then
    warn "性能計測に必須の requirements-bench.txt がありません。"
    note "完全な checkout または配布物を配置し直して、requirements-bench.txt を含むことを確認してから再実行してください。"
    return 1
  fi
  if [[ -x "$LB_ROOT/.venv/Scripts/python.exe" ]]; then
    python_bin="$LB_ROOT/.venv/Scripts/python.exe"
  elif command -v python3 >/dev/null 2>&1; then
    python_bin="$(command -v python3)"
  elif command -v python >/dev/null 2>&1; then
    python_bin="$(command -v python)"
  else
    warn "psutil を確認できる Python 3 環境がありません。"
    note "先に setup.ps1 で .venv を作成してから、次の性能計測用依存を導入してください。"
    note '    .\.venv\Scripts\python.exe -m pip install -r .\requirements-bench.txt'
    return 1
  fi
  if ! "$python_bin" -c 'import psutil' >/dev/null 2>&1; then
    warn "このPCのPython環境に性能計測の必須依存 psutil がありません。"
    note "ネット接続中に、このrepo直下のPowerShellで次を実行してください:"
    note '    .\.venv\Scripts\python.exe -m pip install -r .\requirements-bench.txt'
    note "学校PCでも性能run前に同じ導入を済ませ、psutil importを確認してください。"
    return 1
  fi
  return 0
}

evidence_path_ok() {
  local reference="$1"
  local expected_dir
  local resolved
  expected_dir="$(realpath "$LB_ROOT/docs/field/evidence/$F_DATE" 2>/dev/null || true)"
  [[ -n "$expected_dir" ]] || return 1
  [[ -n "$reference" && "$reference" != *$'\n'* && "$reference" == "docs/field/evidence/$F_DATE/"* ]] || return 1
  [[ "$reference" != *".."* && ! -L "$LB_ROOT/$reference" ]] || return 1
  resolved="$(realpath "$LB_ROOT/$reference" 2>/dev/null || true)"
  [[ -n "$resolved" && "$resolved" == "$expected_dir/"* ]] || return 1
  if [[ -f "$resolved" ]]; then
    [[ -s "$resolved" ]]
  elif [[ -d "$resolved" ]]; then
    ! find "$resolved" -type l -print -quit | grep -q . &&
      ! find "$resolved" -type f -size 0 -print -quit | grep -q . &&
      find "$resolved" -type f -size +0c -print -quit | grep -q .
  else
    return 1
  fi
}

all_evidence_paths_ok() {
  local reference
  for reference in "$@"; do
    evidence_path_ok "$reference" || return 1
  done
}

evidence_file_sha_ok() {
  local reference="$1"
  local expected_sha="${2,,}"
  evidence_path_ok "$reference" || return 1
  [[ -f "$LB_ROOT/$reference" && "$expected_sha" =~ ^[[:xdigit:]]{64}$ ]] || return 1
  [[ "$(sha256sum "$LB_ROOT/$reference" | awk '{print $1}')" == "$expected_sha" ]]
}

# perf01_validation_summary RUN OUTPUT — run the single-source validator and
# accept only its exact one-line, LF-terminated, ten-field shell contract.
PERF01_SUMMARY_FIELDS=()
perf01_validation_summary() {
  local run_reference="$1"
  local validation_reference="$2"
  local python_bin=""
  local summary_file=""
  local command_status=0
  local line_count=""
  local last_byte=""
  local index
  PERF01_SUMMARY_FIELDS=()
  [[ "$run_reference" == "docs/field/evidence/$F_DATE/${F_DATE}-perf01-run.json" ]] || return 1
  [[ "$validation_reference" == "docs/field/evidence/$F_DATE/${F_DATE}-perf01-validation.json" ]] || return 1
  evidence_path_ok "$run_reference" || return 1
  if [[ -x "$LB_ROOT/.venv/Scripts/python.exe" ]]; then
    python_bin="$LB_ROOT/.venv/Scripts/python.exe"
  elif command -v python3 >/dev/null 2>&1; then
    python_bin="$(command -v python3)"
  elif command -v python >/dev/null 2>&1; then
    python_bin="$(command -v python)"
  else
    return 1
  fi
  summary_file="$(mktemp)"
  if "$python_bin" "$LB_ROOT/scripts/perf01_evidence.py" validate \
      "$LB_ROOT/$run_reference" --output "$LB_ROOT/$validation_reference" \
      --format shell > "$summary_file"; then
    command_status=0
  else
    command_status=$?
  fi
  line_count="$(wc -l < "$summary_file")"
  last_byte="$(tail -c 1 "$summary_file" | od -An -t u1 | tr -d ' ')"
  if (( command_status != 0 )) || [[ "$line_count" != "1" || "$last_byte" != "10" ]] || grep -q $'\r' "$summary_file"; then
    rm -f -- "$summary_file"
    return 1
  fi
  IFS=$'\t' read -r -a PERF01_SUMMARY_FIELDS < "$summary_file" || true
  rm -f -- "$summary_file"
  [[ ${#PERF01_SUMMARY_FIELDS[@]} -eq 10 ]] || return 1
  [[ "${PERF01_SUMMARY_FIELDS[0]}" == "true" ]] || return 1
  for index in 1 2 3 5 6 7; do
    [[ "${PERF01_SUMMARY_FIELDS[$index]}" =~ ^[0-9]+$ ]] || return 1
  done
  for index in 4 8 9; do
    [[ "${PERF01_SUMMARY_FIELDS[$index]}" =~ ^[0-9]+([.][0-9]+)?$ ]] || return 1
  done
}

# quality_package_summary TSV PROVENANCE — accept only the package validator's
# exact 15-field shell contract; derive ASR mismatch count from its JSON metric.
QUALITY_PACKAGE_FIELDS=()
QUALITY_PACKAGE_ASR_ERRORS=""
quality_package_summary() {
  local tsv_reference="$1"
  local provenance_reference="$2"
  local python_bin=""
  local summary_file=""
  local json_file=""
  local command_status=0
  local line_count=""
  local last_byte=""
  local index
  QUALITY_PACKAGE_FIELDS=()
  QUALITY_PACKAGE_ASR_ERRORS=""
  [[ "$tsv_reference" == "docs/field/evidence/$F_DATE/${F_DATE}-quality-30.tsv" ]] || return 1
  [[ "$provenance_reference" == "docs/field/evidence/$F_DATE/${F_DATE}-quality-provenance.json" ]] || return 1
  all_evidence_paths_ok "$tsv_reference" "$provenance_reference" "$F_SOURCE_SNAPSHOT_START" "$F_SOURCE_SNAPSHOT_END" || return 1
  [[ "$F_EVIDENCE_MANIFEST" == "docs/field/${F_DATE}-evidence-sha256.txt" && -s "$LB_ROOT/$F_EVIDENCE_MANIFEST" ]] || return 1
  if [[ -x "$LB_ROOT/.venv/Scripts/python.exe" ]]; then
    python_bin="$LB_ROOT/.venv/Scripts/python.exe"
  elif command -v python3 >/dev/null 2>&1; then
    python_bin="$(command -v python3)"
  elif command -v python >/dev/null 2>&1; then
    python_bin="$(command -v python)"
  else
    return 1
  fi
  summary_file="$(mktemp)"
  json_file="$(mktemp)"
  if "$python_bin" "$LB_ROOT/scripts/quality_evidence.py" package \
      "$LB_ROOT/$tsv_reference" "$LB_ROOT/$provenance_reference" \
      --root "$LB_ROOT" --field-date "$F_DATE" \
      --source-snapshot-start "$LB_ROOT/$F_SOURCE_SNAPSHOT_START" \
      --source-snapshot-end "$LB_ROOT/$F_SOURCE_SNAPSHOT_END" \
      --manifest "$LB_ROOT/$F_EVIDENCE_MANIFEST" --format shell > "$summary_file"; then
    command_status=0
  else
    command_status=$?
  fi
  line_count="$(wc -l < "$summary_file")"
  last_byte="$(tail -c 1 "$summary_file" | od -An -t u1 | tr -d ' ')"
  if (( command_status != 0 )) || [[ "$line_count" != "1" || "$last_byte" != "10" ]] || grep -q $'\r' "$summary_file"; then
    rm -f -- "$summary_file" "$json_file"
    return 1
  fi
  IFS=$'\t' read -r -a QUALITY_PACKAGE_FIELDS < "$summary_file" || true
  rm -f -- "$summary_file"
  [[ ${#QUALITY_PACKAGE_FIELDS[@]} -eq 15 ]] || { rm -f -- "$json_file"; return 1; }
  [[ "${QUALITY_PACKAGE_FIELDS[0]}" == "true" ]] || { rm -f -- "$json_file"; return 1; }
  for index in 1 2 3 5 7 8 9 10 11 12 13; do
    [[ "${QUALITY_PACKAGE_FIELDS[$index]}" =~ ^[0-9]+$ ]] || { rm -f -- "$json_file"; return 1; }
  done
  for index in 4 6; do
    [[ "${QUALITY_PACKAGE_FIELDS[$index]}" =~ ^[0-9]+[.][0-9]{2}$ ]] || { rm -f -- "$json_file"; return 1; }
  done
  [[ "${QUALITY_PACKAGE_FIELDS[14]}" =~ ^[0-9a-f]{64}$ ]] || { rm -f -- "$json_file"; return 1; }
  if ! "$python_bin" "$LB_ROOT/scripts/quality_evidence.py" package \
      "$LB_ROOT/$tsv_reference" "$LB_ROOT/$provenance_reference" \
      --root "$LB_ROOT" --field-date "$F_DATE" \
      --source-snapshot-start "$LB_ROOT/$F_SOURCE_SNAPSHOT_START" \
      --source-snapshot-end "$LB_ROOT/$F_SOURCE_SNAPSHOT_END" \
      --manifest "$LB_ROOT/$F_EVIDENCE_MANIFEST" --format json > "$json_file"; then
    rm -f -- "$json_file"
    return 1
  fi
  if ! QUALITY_PACKAGE_ASR_ERRORS="$("$python_bin" -c '
import json
import sys


def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def reject_constant(value):
    raise ValueError(f"non-finite JSON value: {value}")


with open(sys.argv[1], encoding="utf-8") as handle:
    payload = json.load(
        handle,
        object_pairs_hook=strict_object,
        parse_constant=reject_constant,
    )
metrics = payload.get("metrics") if isinstance(payload, dict) else None
scope = payload.get("scope") if isinstance(payload, dict) else None
value = metrics.get("asr_mismatch_row_count") if isinstance(metrics, dict) else None
if (
    payload.get("passed") is not True
    or not isinstance(scope, dict)
    or scope.get("manifest_references_checked") is not True
    or type(value) is not int
    or value < 0
):
    raise SystemExit(1)
print(value)
' "$json_file")"; then
    rm -f -- "$json_file"
    return 1
  fi
  rm -f -- "$json_file"
  [[ "$QUALITY_PACKAGE_ASR_ERRORS" =~ ^[0-9]+$ ]]
}

