import hashlib
import datetime
import json
import math
import re
import sys
from pathlib import Path


def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def canonical_sha256(value):
    payload = json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def run_index_matches(run_dir, index):
    if not isinstance(index, dict) or not index:
        return False
    for relative, expected_sha in index.items():
        if not isinstance(relative, str) or not isinstance(expected_sha, str):
            return False
        if re.fullmatch(r"[0-9a-f]{64}", expected_sha) is None:
            return False
        try:
            path = (run_dir / relative).resolve()
            path.relative_to(run_dir)
        except (OSError, ValueError, TypeError):
            return False
        if not path.is_file() or path.is_symlink() or sha256(path) != expected_sha:
            return False
    return True


def expected_soak_source_keys(root):
    keys = {
        "scripts/__init__.py",
        "scripts/acceptance.py",
        "scripts/bench.py",
        "scripts/performance_evidence.py",
        "scripts/replay_client.py",
        "scripts/story_tracker.py",
        "scripts/text_metrics.py",
        "config.yaml",
        "docs/qa/stories.tsv",
    }
    keys.update(
        path.resolve().relative_to(root).as_posix()
        for path in root.glob("server/**/*.py")
        if path.is_file()
    )
    return keys


with open(sys.argv[1], encoding="utf-8") as handle:
    payload = json.load(handle)
if not isinstance(payload, dict):
    raise SystemExit(1)
checks = payload.get("checks")
root = Path(sys.argv[4]).resolve()
validation_path = Path(sys.argv[1]).resolve()
expected_manifest = sys.argv[5]
expected_report = sys.argv[6]
expected_audio_sha = sys.argv[7].lower()
expected_asr = sys.argv[8]
expected_engine = sys.argv[9]
binding = payload.get("binding")
metrics = payload.get("metrics")
system = payload.get("system")
hardware = payload.get("hardware")
required_top_level = {
    "schema_version", "kind", "passed", "cache_mode", "run_dir", "manifest",
    "primary_report", "validator_sha256", "source_snapshot_sha256",
    "runtime_snapshot_sha256", "system_snapshot_sha256", "hardware_snapshot_sha256",
    "host_fingerprint_sha256", "hardware_collected_at",
    "started_at", "finished_at", "manifest_sha256", "primary_report_sha256",
    "system", "hardware", "binding", "checks", "metrics",
}
required_binding = {
    "minutes", "students", "audio_sha256", "corpus", "asr", "engine", "langs",
    "disconnect_every_s", "partial", "drain_seconds", "no_config_update",
    "effective_config",
}
required_checks = {
    "measurement_and_drain_complete", "ten_students_in_english_and_chinese",
    "continuous_resource_coverage", "no_crash_or_error",
    "standard_load_without_disconnect_injection", "real_asr_and_mt_work_observed",
    "cache_mode_effective", "report_arguments_match_manifest",
    "effective_config_matches_manifest", "windows_system_metadata",
    "manifest_complete_and_current", "arguments_at_least_45_minutes",
    "arguments_ten_students", "real_audio_input", "real_asr", "real_mt",
    "no_config_update", "report_engines_match_arguments", "audio_hash_matches",
    "primary_report_hash_matches", "arguments_out_dir_matches_run",
    "run_dir_binds_validation_host", "windows_hardware_snapshot",
    "school_hardware_supported", "report_matches_hardware",
    "hardware_collected_immediately_after_run",
}
required_checks.add("rss_within_5000_mb" if sys.argv[2] == "on" else "cpu_observed")
if sys.argv[2] == "on":
    required_checks.add("memory_not_increasing")
sha_fields = (
    "validator_sha256", "source_snapshot_sha256", "runtime_snapshot_sha256",
    "system_snapshot_sha256", "hardware_snapshot_sha256", "host_fingerprint_sha256", "manifest_sha256",
    "primary_report_sha256",
)
valid_hashes = all(
    isinstance(payload.get(key), str)
    and re.fullmatch(r"[0-9a-f]{64}", payload[key]) is not None
    for key in sha_fields
)
system_hash_matches = (
    isinstance(system, dict)
    and payload.get("system_snapshot_sha256")
    == hashlib.sha256(
        json.dumps(
            {
                key: system.get(key)
                for key in ("cpu", "cores", "threads", "ram_gb", "os", "python")
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
)
required_hardware = {
    "schema_version", "installed_memory_source", "os_visible_memory_source",
    "os_version_source", "processor_source", "os_release", "os_build_number",
    "os_product_type", "cpu_manufacturer", "cpu_name", "cpu_physical_cores",
    "cpu_logical_processors", "memory_installed_bytes", "memory_os_visible_bytes",
}


def positive_int(value):
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def normalized_text(value):
    return " ".join(value.split()).casefold() if isinstance(value, str) else ""


hardware_hash_matches = (
    isinstance(hardware, dict)
    and set(hardware) == required_hardware
    and type(hardware.get("schema_version")) is int
    and hardware["schema_version"] == 1
    and hardware.get("installed_memory_source") == "GetPhysicallyInstalledSystemMemory"
    and hardware.get("os_visible_memory_source") == "GlobalMemoryStatusEx"
    and hardware.get("os_version_source") == "sys.getwindowsversion"
    and hardware.get("processor_source")
    == r"HKLM\HARDWARE\DESCRIPTION\System\CentralProcessor\0"
    and hardware.get("os_release") == "11"
    and positive_int(hardware.get("os_build_number"))
    and hardware["os_build_number"] >= 22000
    and hardware.get("os_product_type") == 1
    and normalized_text(hardware.get("cpu_manufacturer")) == "genuineintel"
    and "intel" in normalized_text(hardware.get("cpu_name"))
    and "core" in normalized_text(hardware.get("cpu_name"))
    and re.search(r"(?<![a-z0-9])i5(?:[-\s]|$)", hardware["cpu_name"], re.I)
    is not None
    and positive_int(hardware.get("cpu_physical_cores"))
    and positive_int(hardware.get("cpu_logical_processors"))
    and hardware["cpu_logical_processors"] >= hardware["cpu_physical_cores"]
    and positive_int(hardware.get("memory_installed_bytes"))
    and 8 * 1024**3 <= hardware["memory_installed_bytes"] <= 16 * 1024**3
    and positive_int(hardware.get("memory_os_visible_bytes"))
    and hardware["memory_os_visible_bytes"] <= hardware["memory_installed_bytes"]
    and payload.get("hardware_snapshot_sha256") == canonical_sha256(hardware)
)
try:
    collected_at = datetime.datetime.fromisoformat(payload["hardware_collected_at"])
    hardware_finished_at = datetime.datetime.fromisoformat(payload["finished_at"])
    hardware_delay = collected_at - hardware_finished_at
    valid_hardware_time = (
        collected_at.utcoffset() is not None
        and hardware_finished_at.utcoffset() is not None
        and 0 <= hardware_delay.total_seconds() <= 15 * 60
    )
except (KeyError, OverflowError, TypeError, ValueError):
    valid_hardware_time = False
valid_binding = (
    isinstance(binding, dict)
    and required_binding <= set(binding)
    and isinstance(binding.get("minutes"), (int, float))
    and not isinstance(binding.get("minutes"), bool)
    and math.isfinite(float(binding["minutes"]))
    and binding["minutes"] >= 45
    and binding.get("students") == 10
    and binding.get("audio_sha256") == expected_audio_sha
    and re.fullmatch(r"[0-9a-f]{64}", expected_audio_sha) is not None
    and binding.get("asr") == expected_asr
    and binding.get("engine") == expected_engine
    and isinstance(binding.get("langs"), list)
    and all(isinstance(lang, str) for lang in binding["langs"])
    and set(binding["langs"]) == {"en", "zh"}
    and binding.get("disconnect_every_s") is None
    and binding.get("partial") is None
    and isinstance(binding.get("drain_seconds"), (int, float))
    and not isinstance(binding.get("drain_seconds"), bool)
    and math.isfinite(float(binding["drain_seconds"]))
    and binding["drain_seconds"] >= 0
    and binding.get("no_config_update") is True
    and isinstance(binding.get("effective_config"), str)
    and bool(binding["effective_config"])
    and isinstance(metrics, dict)
    and metrics.get("audio_sha256") == expected_audio_sha
    and isinstance(system, dict)
    and set(("cpu", "cores", "threads", "ram_gb", "os", "python", "date")) <= set(system)
)
try:
    validation_path.relative_to(root)
    run_dir = validation_path.parent
    run_dir_relative = run_dir.relative_to(root).as_posix()
    manifest_relative = payload.get("manifest")
    report_relative = payload.get("primary_report")
    manifest_path = (root / manifest_relative).resolve()
    report_path = (root / report_relative).resolve()
    manifest_path.relative_to(run_dir)
    report_path.relative_to(run_dir)
    manifest_bytes = manifest_path.read_bytes()
    report_bytes = report_path.read_bytes()
    manifest = json.loads(manifest_bytes)
    report = json.loads(report_bytes)
    report_from_manifest = manifest.get("primary_report")
    report_in_run = report_path.relative_to(run_dir).as_posix()
    arguments = manifest.get("arguments")
    source_hashes = manifest.get("source_hashes")
    runtime = manifest.get("runtime")
    runtime_asset_hashes = manifest.get("runtime_asset_hashes")
    input_hashes = manifest.get("input_hashes")
    configuration = manifest.get("configuration")
    effective = configuration.get("effective") if isinstance(configuration, dict) else None
    artifacts = manifest.get("artifacts")
    results = report.get("results") if isinstance(report, dict) else None
    if not isinstance(results, list) or len(results) != 1:
        raise ValueError("primary report must contain exactly one result")
    result = results[0]
    if not isinstance(result, dict) or not isinstance(arguments, dict):
        raise ValueError("report result and manifest arguments must be objects")
    reported_system = report.get("system")
    normalized_system = (
        {
            key: reported_system.get(key)
            for key in ("cpu", "cores", "threads", "ram_gb", "os", "python", "date")
        }
        if isinstance(reported_system, dict)
        else None
    )
    hardware_matches_report = (
        hardware_hash_matches
        and isinstance(normalized_system, dict)
        and normalized_text(normalized_system.get("cpu"))
        == normalized_text(hardware.get("cpu_name"))
        and normalized_system.get("cores") == hardware.get("cpu_physical_cores")
        and normalized_system.get("threads") == hardware.get("cpu_logical_processors")
        and normalized_system.get("ram_gb")
        == round(hardware["memory_os_visible_bytes"] / 1e9, 1)
        and isinstance(normalized_system.get("os"), str)
        and re.match(r"^Windows 11(?:\b|$)", normalized_system["os"], re.I)
        is not None
    )
    snapshots_match_files = (
        isinstance(source_hashes, dict)
        and bool(source_hashes)
        and set(source_hashes) == expected_soak_source_keys(root)
        and run_index_matches(root, source_hashes)
        and isinstance(runtime, dict)
        and bool(runtime)
        and isinstance(runtime_asset_hashes, dict)
        and bool(runtime_asset_hashes)
        and isinstance(normalized_system, dict)
        and payload.get("source_snapshot_sha256") == canonical_sha256(source_hashes)
        and payload.get("runtime_snapshot_sha256")
        == canonical_sha256(
            {"runtime": runtime, "runtime_asset_hashes": runtime_asset_hashes}
        )
        and payload.get("system") == normalized_system
        and hardware_matches_report
        and payload.get("system_snapshot_sha256")
        == canonical_sha256(
            {
                key: normalized_system.get(key)
                for key in ("cpu", "cores", "threads", "ram_gb", "os", "python")
            }
        )
    )
    bindings_match_files = (
        isinstance(binding, dict)
        and binding.get("minutes") == arguments.get("minutes")
        and binding.get("students") == arguments.get("students")
        and binding.get("corpus") == arguments.get("corpus")
        and binding.get("asr") == arguments.get("asr")
        and binding.get("engine") == arguments.get("engine")
        and binding.get("langs") == result.get("langs")
        and binding.get("disconnect_every_s") == arguments.get("disconnect_every_s")
        and binding.get("partial") == arguments.get("partial")
        and binding.get("drain_seconds") == arguments.get("drain_seconds")
        and binding.get("no_config_update") == arguments.get("no_config_update")
        and binding.get("effective_config") == result.get("effective_config")
        and isinstance(arguments.get("out_dir"), str)
        and (
            Path(arguments["out_dir"]).resolve()
            if Path(arguments["out_dir"]).is_absolute()
            else (root / arguments["out_dir"]).resolve()
        )
        == run_dir
        and isinstance(effective, dict)
        and len(effective) == 1
        and result.get("effective_config") in effective
        and isinstance(input_hashes, dict)
        and list(input_hashes.values()) == [expected_audio_sha]
        and (
            (sys.argv[2] == "on" and arguments.get("mt_cache_size") is None)
            or (sys.argv[2] == "off" and arguments.get("mt_cache_size") == 0)
        )
        and result.get("mt_cache_size") == arguments.get("mt_cache_size")
        and result.get("disconnect_every_s") is None
        and result.get("disconnects") == 0
        and result.get("reconnect_failures") == 0
    )
    manifest_sha = hashlib.sha256(manifest_bytes).hexdigest()
    report_sha = hashlib.sha256(report_bytes).hexdigest()
    copied_run_files_match = (
        run_index_matches(run_dir, artifacts)
        and run_index_matches(run_dir, effective)
    )
    sealed_files_match = (
        payload.get("run_dir") == run_dir_relative
        and validation_path.name == "field-validation.json"
        and manifest_path == run_dir / "source-manifest.json"
        and manifest_relative == manifest_path.relative_to(root).as_posix()
        and report_relative == report_path.relative_to(root).as_posix()
        and (not expected_manifest or manifest_relative == expected_manifest)
        and (not expected_report or report_relative == expected_report)
        and manifest.get("complete") is True
        and payload.get("started_at") == manifest.get("started_at")
        and payload.get("finished_at") == manifest.get("finished_at")
        and report_from_manifest == report_in_run
        and isinstance(artifacts, dict)
        and artifacts.get(report_in_run) == report_sha
        and payload.get("manifest_sha256") == manifest_sha
        and payload.get("primary_report_sha256") == report_sha
        and run_dir.name.endswith(
            f"-{payload['host_fingerprint_sha256'][:16]}-school-cache-{sys.argv[2]}"
        )
        and snapshots_match_files
        and bindings_match_files
        and copied_run_files_match
        and manifest_path.is_file()
        and report_path.is_file()
        and not manifest_path.is_symlink()
        and not report_path.is_symlink()
    )
except (OSError, ValueError, TypeError, AttributeError, json.JSONDecodeError):
    sealed_files_match = False
valid = (
    required_top_level <= set(payload)
    and payload.get("schema_version") == 2
    and payload.get("kind") == "field-performance-validation"
    and payload.get("passed") is True
    and payload.get("cache_mode") == sys.argv[2]
    and payload.get("validator_sha256") == sys.argv[3]
    and isinstance(checks, dict)
    and required_checks <= set(checks)
    and all(value is True for value in checks.values())
    and valid_hashes
    and system_hash_matches
    and hardware_hash_matches
    and valid_hardware_time
    and valid_binding
    and sealed_files_match
)
raise SystemExit(0 if valid else 1)
PY
}

performance_pair_passed() {
  local cache_on_reference="$1"
  local cache_off_reference="$2"
  local cache_on_manifest="$3"
  local cache_on_report="$4"
  local cache_off_manifest="$5"
  local cache_off_report="$6"
  local expected_audio_sha="$7"
  local expected_asr="$8"
  local expected_engine="$9"
  local python_bin
  validation_json_passed "$cache_on_reference" "on" "$cache_on_manifest" "$cache_on_report" "$expected_audio_sha" "$expected_asr" "$expected_engine" || return 1
  validation_json_passed "$cache_off_reference" "off" "$cache_off_manifest" "$cache_off_report" "$expected_audio_sha" "$expected_asr" "$expected_engine" || return 1
  if [[ -x "$LB_ROOT/.venv/Scripts/python.exe" ]]; then
    python_bin="$LB_ROOT/.venv/Scripts/python.exe"
  elif command -v python3 >/dev/null 2>&1; then
    python_bin="$(command -v python3)"
  else
    python_bin="$(command -v python)"
  fi
  "$python_bin" - "$LB_ROOT/$cache_on_reference" "$LB_ROOT/$cache_off_reference" <<'PY'
import datetime
import json
import re
import sys

with open(sys.argv[1], encoding="utf-8") as handle:
    cache_on = json.load(handle)
with open(sys.argv[2], encoding="utf-8") as handle:
    cache_off = json.load(handle)
cache_on_binding = cache_on.get("binding")
cache_off_binding = cache_off.get("binding")
same_binding = (
    isinstance(cache_on_binding, dict)
    and isinstance(cache_off_binding, dict)
    and {key: value for key, value in cache_on_binding.items() if key != "effective_config"}
    == {key: value for key, value in cache_off_binding.items() if key != "effective_config"}
    and cache_on_binding.get("effective_config") != cache_off_binding.get("effective_config")
)
distinct_runs = (
    all(
        isinstance(payload.get(key), str) and bool(payload[key])
        for payload in (cache_on, cache_off)
        for key in ("run_dir", "manifest", "primary_report")
    )
    and cache_on["run_dir"] != cache_off["run_dir"]
    and cache_on["manifest"] != cache_off["manifest"]
    and cache_on["primary_report"] != cache_off["primary_report"]
)
same_snapshot = (
    isinstance(cache_on.get("source_snapshot_sha256"), str)
    and re.fullmatch(r"[0-9a-f]{64}", cache_on["source_snapshot_sha256"])
    and cache_on["source_snapshot_sha256"]
    == cache_off.get("source_snapshot_sha256")
)
same_runtime = (
    isinstance(cache_on.get("runtime_snapshot_sha256"), str)
    and re.fullmatch(r"[0-9a-f]{64}", cache_on["runtime_snapshot_sha256"])
    and cache_on["runtime_snapshot_sha256"]
    == cache_off.get("runtime_snapshot_sha256")
)
same_system = (
    isinstance(cache_on.get("system_snapshot_sha256"), str)
    and re.fullmatch(r"[0-9a-f]{64}", cache_on["system_snapshot_sha256"])
    and cache_on["system_snapshot_sha256"]
    == cache_off.get("system_snapshot_sha256")
    and isinstance(cache_on.get("system"), dict)
    and isinstance(cache_off.get("system"), dict)
    and all(
        cache_on["system"].get(key) == cache_off["system"].get(key)
        for key in ("cpu", "cores", "threads", "ram_gb", "os", "python")
    )
)
same_hardware = (
    isinstance(cache_on.get("hardware_snapshot_sha256"), str)
    and re.fullmatch(r"[0-9a-f]{64}", cache_on["hardware_snapshot_sha256"])
    and cache_on["hardware_snapshot_sha256"]
    == cache_off.get("hardware_snapshot_sha256")
    and isinstance(cache_on.get("hardware"), dict)
    and cache_on.get("hardware") == cache_off.get("hardware")
)
same_host = (
    isinstance(cache_on.get("host_fingerprint_sha256"), str)
    and re.fullmatch(r"[0-9a-f]{64}", cache_on["host_fingerprint_sha256"])
    and cache_on["host_fingerprint_sha256"]
    == cache_off.get("host_fingerprint_sha256")
)
try:
    on_started = datetime.datetime.fromisoformat(cache_on["started_at"])
    on_finished = datetime.datetime.fromisoformat(cache_on["finished_at"])
    on_collected = datetime.datetime.fromisoformat(cache_on["hardware_collected_at"])
    off_started = datetime.datetime.fromisoformat(cache_off["started_at"])
    off_finished = datetime.datetime.fromisoformat(cache_off["finished_at"])
    off_collected = datetime.datetime.fromisoformat(cache_off["hardware_collected_at"])
    sequential_runs = (
        on_started < on_finished <= on_collected <= off_started < off_finished
        <= off_collected
        and (on_finished - on_started).total_seconds() >= 45 * 60
        and (off_finished - off_started).total_seconds() >= 45 * 60
        and (off_started - on_finished).total_seconds() <= 4 * 60 * 60
    )
except (KeyError, OverflowError, TypeError, ValueError):
    sequential_runs = False
raise SystemExit(
    0
    if same_binding
    and distinct_runs
    and same_snapshot
    and same_runtime
    and same_system
    and same_hardware
    and same_host
    and sequential_runs
    else 1
)
PY
}

if ! field_verification_preflight; then
  exit 2
fi

banner "LinguaBridge 実地検証（イシュー #19）"

# ══════════════════════════════════════════════════════════════════════════
# 前日（インターネット接続下・学校PC）
# ══════════════════════════════════════════════════════════════════════════

# ── 1 ────────────────────────────────────────────────────────────────────
stage "実施記録の基礎情報"
say "レポートの見出しになる情報です。あとから誰が読んでも条件が分かるように。"
say ""
ask F_DATE   "実施日 (YYYY-MM-DD):"
[[ -z "$F_DATE" ]] && F_DATE="$(date +%F)"
while [[ ! "$F_DATE" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || [[ "$(date -d "$F_DATE" +%F 2>/dev/null || true)" != "$F_DATE" ]]; do
  warn "実施日は YYYY-MM-DD だけを使用します（レポートのファイル名にも使います）。"
  ask F_DATE "実施日 (YYYY-MM-DD):"
done
ask F_TESTER "実施者:"
ask F_PC     "学校PC（型番・CPU・RAM）:"
ask F_CB     "Chromebook（台数・型番）:"
ask F_PHONE  "その他端末（iPhone等・台数）:"
write_env F_DATE "$F_DATE"
write_env F_TESTER "$F_TESTER"
write_env F_PC "$F_PC"
write_env F_CB "$F_CB"
write_env F_PHONE "$F_PHONE"
note "開発機は Ryzen 7 8840U (8C/16T・RAM 16.4GB)。学校PCのコア数が少ないと"
note "CPU中央値だけは結論が変わりうるので、型番は正確に。"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "学校PCへコードを配置する（前日・要ネット）"
say "授業当日をネット不要にするため、配置とモデル取得は前日までに済ませます。"
say ""
step "学校PCにネットがあるなら clone:"
note "    git clone $REPO_URL"
note "    cd LinguaBridge"
note "    git checkout localServer2"
step "ネットが無い／制限されているなら USB でフォルダごとコピー。"
warn ".venv フォルダはコピーしない（学校PC側で作り直される。OSやCPUに依存する）"
warn "OneDrive 同期フォルダの下には置かない（モデル4GBが同期対象になる・plan.md R-08）"
say ""
ask F_DEPLOY "配置方法 (clone / copy):"
ask F_PATH   "学校PC上の配置パス:"
step "性能runと当日試験に使う学校PCの配置folderで、全sourceの開始snapshotを1回だけ作る:"
note "    python scripts\\field_story_evidence.py snapshot-sources --field-date $F_DATE --phase start"
note "    python commandが無くpy launcherを使うPCでは、先頭を py -3.12 に置き換える。"
note "    docs\\field\\evidence\\$F_DATE\\school-source-start.json が生成されたことを確認する。"
note "    F_DATEは実行時の学校PCローカル日付と一致必須。別日の旧証拠を当日証拠として再ラベルしない。"
warn "このsnapshotより前に作業を開始しない。既存fileを上書きせず、同じcheckout・同じ学校PCで最後まで続ける。"
write_env F_DEPLOY "$F_DEPLOY"
write_env F_PATH "$F_PATH"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "OPS-02 — 実モデル取得を意図的に中断し、再実行を確認する"
say "スタブではなく、実際の初回取得を壊して戻るかを確認します。"
warn "必ず許可された新規／隔離Windowsで実施。既存ホストのモデルや .venv は削除しない。"
warn "次のOPS-01には別のクリーン環境、または中断前のclean snapshotへの復元が必要です。"
say ""
ask F_RETRY_ACTION "このステージの扱い (今回実施 / 既存証拠を再利用 / 未実施):"
if [[ "$F_RETRY_ACTION" == "今回実施" ]]; then
  F_RETRY_EXECUTED="実施"
  step "start.bat を起動し、少なくとも1モデルが完了して manifest.json に載るまで待つ"
  note '    別PowerShellで: Get-Content "$env:LOCALAPPDATA\LinguaBridge\models\manifest.json"'
  step "完了済みモデル配下の全payloadを再帰列挙し、相対path・byte・mtime・各ファイルSHA-256とmanifestを控える"
  step "次の大容量モデルを取得中に、セットアップ側のPowerShellを Ctrl-C で1回だけ中断する"
  step '配置フォルダで Test-Path ".venv\.setup-complete" を実行し、False を確認する'
  step "先生ページが自動で開かず、授業サーバーも起動していないことを確認する"
  step "同じ start.bat を再実行し、セットアップ完了まで待つ"
  step "先に完了したモデルのpayload一覧（相対path・byte・mtime・SHA-256）が前後一致することを確認する"
  note "    完成ファイルは再利用される。取得途中の単一ファイルは先頭から再取得される場合がある。"
  step "再実行ログと、前後のmanifest／Get-Item／Get-FileHash出力を証拠ファイルに保存する"
elif [[ "$F_RETRY_ACTION" == "既存証拠を再利用" ]]; then
  F_RETRY_EXECUTED="実施済み証拠を再利用"
  note "保存済み回答が各入力の既定値になります。証拠を見直し、Enterで保持してください。"
else
  F_RETRY_EXECUTED="未実施"
  F_RETRY_ENV=""
  F_RETRY_DONE_MODEL=""
  F_RETRY_DONE_STATE=""
  F_RETRY_DONE_AFTER=""
  F_RETRY_ACTIVE=""
  F_RETRY_MARKER="未確認"
  F_RETRY_SERVER="未確認"
  F_RETRY_REUSED="未確認"
  F_RETRY_PARTIAL="未確認"
  F_RETRY_RESULT="未確認"
  F_RETRY_MANIFESTS=""
  F_RETRY_EVIDENCE=""
  warn "OPS-02 は部分確認のまま。隔離Windowsを用意して、このステージを再実行してください。"
  SKIPPED+=("OPS-02: 隔離Windowsで実モデル取得の中断・再実行証拠を取る")
fi
if [[ "$F_RETRY_EXECUTED" != "未実施" ]]; then
  say ""
  ask F_RETRY_ENV         "OPS-02用のVM／PC／clean snapshot識別子:"
  ask F_RETRY_DONE_MODEL  "中断前に完了していたモデル名:"
  ask F_RETRY_DONE_STATE  "中断前payload一覧の単一repo相対path（docs/field/evidence/$F_DATE/ 配下）:"
  ask F_RETRY_ACTIVE      "中断時に取得中だったモデル／ファイル名:"
  ask F_RETRY_MARKER      "中断後の完了マーカー確認 (False / それ以外):"
  ask F_RETRY_SERVER      "中断後に授業サーバーが起動していない？ (可 / 否):"
