stage "学校PCで45分リプレイを2本実行する（#17 の自動計測）"
say "実授業音源を45分流し、学校PCのサーバー遅延・メモリ・CPUを記録します。"
say ""
ask F_ACC_AUDIO     "45分以上の実授業WAVパス（16kHz mono）:"
ask F_ACC_AUDIO_MIN "音源の実時間 (分):"
ask F_ACC_ASR       "固定するASR (sherpa / faster-whisper):"
ask F_ACC_ENGINE    "固定する翻訳エンジン (hy-mt2 / nllb):"
step "学校PCの PowerShell で音源ハッシュを取り、値を控える:"
note "    (Get-FileHash -Algorithm SHA256 \"$F_ACC_AUDIO\").Hash"
ask F_ACC_AUDIO_SHA "実授業WAVのSHA-256:"
ask F_ACC_AUDIO_EVIDENCE "個人情報を除いた音源メタデータ・実時間・SHA-256のrepo相対path（docs/field/evidence/$F_DATE/ 配下）:"
step "学校PCの PowerShell で、空の出力先を2つ作る名前を決める:"
note '    $stamp = Get-Date -Format yyyyMMdd-HHmmss'
note '    $sha = [Security.Cryptography.SHA256]::Create()'
note '    $hostHash = (($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($env:COMPUTERNAME.Trim())) | ForEach-Object ToString x2) -join "")'
note '    $sha.Dispose()'
note '    $hostPrefix = $hostHash.Substring(0, 16)'
note "    \$cached = \"docs\\field\\evidence\\$F_DATE\\\$stamp-\$hostPrefix-school-cache-on\""
note "    \$noCache = \"docs\\field\\evidence\\$F_DATE\\\$stamp-\$hostPrefix-school-cache-off\""
step "1本目（通常キャッシュ）を実行:"
note "    .venv\\Scripts\\python.exe scripts\\replay_client.py --minutes 45 --students 10 --audio \"$F_ACC_AUDIO\" --asr $F_ACC_ASR --engine $F_ACC_ENGINE --out-dir \"\$cached\" --no-config-update"
step "1本目の終了直後、同じ学校PC・同じcheckout・同じ.venvでsealed manifestとJSON実測値を検証する:"
note "    .venv\\Scripts\\python.exe scripts\\validate_field_performance.py \"\$cached\" --cache-mode on --audio-sha256 $F_ACC_AUDIO_SHA --output \"\$cached\\field-validation.json\""
step "1本目が完全終了してから4時間以内に、同じ学校PCで2本目（翻訳キャッシュ無効）を実行:"
note "    .venv\\Scripts\\python.exe scripts\\replay_client.py --minutes 45 --students 10 --audio \"$F_ACC_AUDIO\" --asr $F_ACC_ASR --engine $F_ACC_ENGINE --mt-cache-size 0 --out-dir \"\$noCache\" --no-config-update"
step "2本目の終了直後にも同じ検証を行い、結果JSONをrun内へ保存する:"
note "    .venv\\Scripts\\python.exe scripts\\validate_field_performance.py \"\$noCache\" --cache-mode off --audio-sha256 $F_ACC_AUDIO_SHA --output \"\$noCache\\field-validation.json\""
say ""
warn "この2本では物理ブラウザを接続しない。--students 10 がPython擬似生徒10名を作るため、接続すると20名負荷になります。"
warn "各 --out-dir は実行前に存在してはいけません。同じ出力先の再利用・2本での共有は拒否されます。"
warn "レポート遅延はサーバー送出／Python WS受信まで。物理ブラウザDOM表示はPhase C-4で別に全件測ります。"
warn "2本目（--mt-cache-size 0）はMT負荷の上界。授業用設定を変えないため --no-config-update を外さない。"
note "翻訳キャッシュ無効＝MT負荷の上界。開発機の CPU中央値 30.1%（論理16コアで約4.8コア相当）は"
note "論理コア数に直接効くので、コアの少ない実機ではここだけ結論が変わりうる。"
say ""
ask F_ACC_MED     "通常キャッシュrunのレポート遅延 中央値 (秒):"
ask F_ACC_MAX     "通常キャッシュrunのレポート遅延 最大 (秒):"
ask F_ACC_RSS     "通常キャッシュrunのピークRSS (MB・基準 5000以下):"
ask F_ACC_CRASHES "通常キャッシュrunのクラッシュ数:"
ask F_ACC_ERRORS  "通常キャッシュrunのerrors件数:"
ask F_ACC_CPU     "CPU中央値 キャッシュ無効時 (%):"
ask F_ACC_REPORT  "通常キャッシュrunのJSONレポートrepo相対path（docs/field/evidence/$F_DATE/ 配下）:"
ask F_ACC_MANIFEST "通常キャッシュrunのsource-manifest.json repo相対path:"
ask F_ACC_VALIDATION "通常キャッシュrunのfield-validation.json repo相対path:"
ask F_ACC_VALIDATED "通常キャッシュrunのvalidatorがpassed=true？ (可 / 否):"
ask F_ACC_NOCACHE_REPORT "キャッシュ無効runのJSONレポートrepo相対path（docs/field/evidence/$F_DATE/ 配下）:"
ask F_ACC_NOCACHE_MANIFEST "キャッシュ無効runのsource-manifest.json repo相対path:"
ask F_ACC_NOCACHE_VALIDATION "キャッシュ無効runのfield-validation.json repo相対path:"
ask F_ACC_NOCACHE_VALIDATED "キャッシュ無効runのvalidatorがpassed=true？ (可 / 否):"
F_PERF02="否"
if [[ "$F_ACC_VALIDATED" == "可" && "$F_ACC_CRASHES" == "0" && "$F_ACC_ERRORS" == "0" && -n "$F_ACC_REPORT" && -n "$F_ACC_MANIFEST" && -n "$F_ACC_VALIDATION" && "$F_ACC_AUDIO_SHA" =~ ^[[:xdigit:]]{64}$ ]]; then
  if awk -v minutes="$F_ACC_AUDIO_MIN" -v rss="$F_ACC_RSS" 'BEGIN {
    number="^[0-9]+([.][0-9]+)?$"
    exit !(minutes ~ number && rss ~ number && minutes >= 45 && rss <= 5000)
  }'; then
    F_PERF02="可"
  fi
fi
F_ACC_NOCACHE_OK="否"
if [[ "$F_ACC_NOCACHE_VALIDATED" == "可" && -n "$F_ACC_NOCACHE_REPORT" && -n "$F_ACC_NOCACHE_MANIFEST" && -n "$F_ACC_NOCACHE_VALIDATION" ]]; then
