fi
F_ACC_VERDICT="$F_PERF02"
if [[ "$F_PERF02" != "可" ]]; then
  warn "45分以上・プロセスツリーRSS最大5000MB以下・クラッシュ/エラー0・manifest付きrunが揃わないため、PERF-02は部分確認のままです。"
