  SKIPPED+=("性能補助証拠: 学校Windowsで別out-dirのキャッシュ無効45分runをsealed検証する")
fi
write_env F_ACC_AUDIO "$F_ACC_AUDIO"
write_env F_ACC_AUDIO_MIN "$F_ACC_AUDIO_MIN"
write_env F_ACC_ASR "$F_ACC_ASR"
write_env F_ACC_ENGINE "$F_ACC_ENGINE"
write_env F_ACC_AUDIO_SHA "$F_ACC_AUDIO_SHA"
write_env F_ACC_AUDIO_EVIDENCE "$F_ACC_AUDIO_EVIDENCE"
write_env F_ACC_MED "$F_ACC_MED"
write_env F_ACC_MAX "$F_ACC_MAX"
write_env F_ACC_RSS "$F_ACC_RSS"
write_env F_ACC_CRASHES "$F_ACC_CRASHES"
write_env F_ACC_ERRORS "$F_ACC_ERRORS"
write_env F_ACC_CPU "$F_ACC_CPU"
write_env F_ACC_VERDICT "$F_ACC_VERDICT"
write_env F_PERF02 "$F_PERF02"
write_env F_ACC_NOCACHE_OK "$F_ACC_NOCACHE_OK"
write_env F_ACC_REPORT "$F_ACC_REPORT"
write_env F_ACC_MANIFEST "$F_ACC_MANIFEST"
write_env F_ACC_VALIDATION "$F_ACC_VALIDATION"
write_env F_ACC_VALIDATED "$F_ACC_VALIDATED"
write_env F_ACC_NOCACHE_REPORT "$F_ACC_NOCACHE_REPORT"
write_env F_ACC_NOCACHE_MANIFEST "$F_ACC_NOCACHE_MANIFEST"
write_env F_ACC_NOCACHE_VALIDATION "$F_ACC_NOCACHE_VALIDATION"
write_env F_ACC_NOCACHE_VALIDATED "$F_ACC_NOCACHE_VALIDATED"
note "ここまでが前日分。当日の朝に続きから再開できます（Ctrl-C で中断可）。"
