  if awk -v start="$F_C2_START_EPOCH" -v finish="$F_C2_END_EPOCH" -v seconds="$F_C2_SEC" 'BEGIN {
    number="^[0-9]+([.][0-9]+)?$"
    delta=finish-start
    difference=delta-seconds
    if (difference < 0) difference=-difference
    exit !(seconds ~ number && seconds > 0 && finish >= start && difference <= 1)
  }'; then
    F_C2_TIME_CHECK="可"
  fi
fi
