fi
write_env F_C2 "$F_C2"
write_env F_C2_START "$F_C2_START"
write_env F_C2_END "$F_C2_END"
write_env F_C2_SEC "$F_C2_SEC"
write_env F_C2_ZERO "$F_C2_ZERO"
write_env F_C2_CONNECTED "$F_C2_CONNECTED"
write_env F_C2_QR_COUNT "$F_C2_QR_COUNT"
write_env F_C2_MANUAL_COUNT "$F_C2_MANUAL_COUNT"
write_env F_C2_LANGS "$F_C2_LANGS"
write_env F_C2_NETWORK_MATCH "$F_C2_NETWORK_MATCH"
