F_C6_NUMBERS=0
F_C6_DISTINCT=0
F_C6_DOMAIN_COVERAGE=0
F_C6_ACOUSTIC_COVERAGE=0
QUALITY_STATUS=127
QUALITY_SUMMARY=""
QUALITY_FIELDS=()
QUALITY_CONTRACT_OK="false"
if [[ -n "$QUALITY_PYTHON" ]]; then
  if QUALITY_SUMMARY="$("$QUALITY_PYTHON" "$LB_ROOT/scripts/quality_evidence.py" "$QUALITY_FILE" --format shell)"; then
    QUALITY_STATUS=0
  else
    QUALITY_STATUS=$?
  fi
  # Native Windows Python may leave CR after command substitution removes LF.
  QUALITY_SUMMARY="${QUALITY_SUMMARY%$'\r'}"
  if [[ "$QUALITY_SUMMARY" != *$'\n'* && "$QUALITY_SUMMARY" != *$'\r'* ]]; then
    IFS=$'\t' read -r -a QUALITY_FIELDS <<< "$QUALITY_SUMMARY"
  fi
  if (( ${#QUALITY_FIELDS[@]} == 11 )); then
    QUALITY_REJOINED="$(IFS=$'\t'; printf '%s' "${QUALITY_FIELDS[*]}")"
    if [[ "$QUALITY_REJOINED" == "$QUALITY_SUMMARY" &&
          ( ( "$QUALITY_STATUS" == "0" && "${QUALITY_FIELDS[0]}" == "true" ) ||
            ( "$QUALITY_STATUS" == "1" && "${QUALITY_FIELDS[0]}" == "false" ) ) &&
          "${QUALITY_FIELDS[1]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[2]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[3]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[4]}" =~ ^[0-9]+\.[0-9]{2}$ &&
          "${QUALITY_FIELDS[5]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[6]}" =~ ^[0-9]+\.[0-9]{2}$ &&
          "${QUALITY_FIELDS[7]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[8]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[9]}" =~ ^[0-9]+$ &&
          "${QUALITY_FIELDS[10]}" =~ ^[0-9]+$ ]]; then
      QUALITY_CONTRACT_OK="true"
    fi
  fi
  if [[ "$QUALITY_CONTRACT_OK" == "true" ]]; then
    F_C6_DATA_PASSED="${QUALITY_FIELDS[0]}"
    F_C6_ROWS="${QUALITY_FIELDS[1]}"
    F_C6_REQUIRED="${QUALITY_FIELDS[2]}"
