    F_C6_EN_SCORE="${QUALITY_FIELDS[4]}"
    F_C6_ZH_COUNT="${QUALITY_FIELDS[5]}"
    F_C6_SCORE="${QUALITY_FIELDS[6]}"
    F_C6_NUMBERS="${QUALITY_FIELDS[7]}"
    F_C6_DISTINCT="${QUALITY_FIELDS[8]}"
    F_C6_DOMAIN_COVERAGE="${QUALITY_FIELDS[9]}"
    F_C6_ACOUSTIC_COVERAGE="${QUALITY_FIELDS[10]}"
  else
    warn "QUAL-01 TSV validatorの終了状態または11フィールド出力が不正です。"
  fi
else
  warn "QUAL-01 TSV validatorを実行できるPythonがありません。"
fi
F_C6_SHA="$(sha256sum "$QUALITY_FILE" | awk '{print $1}')"
note "集計: データ ${F_C6_ROWS}行・No順序 ${F_C6_NUMBERS}/30・異なる原文 ${F_C6_DISTINCT}/30・必須列 ${F_C6_REQUIRED}/30"
