  if [[ "$F_EVIDENCE_DIR" == "$EXPECTED_EVIDENCE_REL" && "$F_EVIDENCE_MANIFEST" == "$EXPECTED_MANIFEST_REL" && -d "$EXPECTED_EVIDENCE_DIR" && ! -L "$EXPECTED_EVIDENCE_DIR" && -s "$EXPECTED_MANIFEST" && ! -L "$EXPECTED_MANIFEST" ]]; then
