      "$FIELD_PYTHON" - "$FIELD_CAPTURE_JSON" \
        "$EXPECTED_EVIDENCE_REL/field-story-evidence.json" \
        "$F_EVIDENCE_MANIFEST" <<'PY'
import json
import re
import sys


def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def reject_constant(value):
    raise ValueError(f"invalid JSON constant: {value}")


try:
    payload = json.loads(
        sys.argv[1],
        object_pairs_hook=strict_object,
        parse_constant=reject_constant,
    )
    required = {
        "bundle",
        "bundle_sha256",
        "manifest",
        "manifest_sha256",
        "approved_candidates",
        "field_complete",
    }
    if not isinstance(payload, dict) or set(payload) != required:
        raise ValueError("unexpected capture JSON fields")
    if payload["bundle"] != sys.argv[2] or payload["manifest"] != sys.argv[3]:
        raise ValueError("capture JSON path mismatch")
    for key in ("bundle_sha256", "manifest_sha256"):
        if not isinstance(payload[key], str) or re.fullmatch(r"[0-9a-f]{64}", payload[key]) is None:
            raise ValueError(f"invalid {key}")
    stories = (
        "OPS-01",
        "OPS-02",
        "OPS-10",
        "OPS-12",
        "STU-11",
        "PERF-01",
        "PERF-02",
        "QUAL-01",
    )
    candidates = payload["approved_candidates"]
    if not isinstance(candidates, list) or any(
        not isinstance(story, str) for story in candidates
    ):
        raise ValueError("invalid approved_candidates type")
    canonical = [story for story in stories if story in candidates]
    if candidates != canonical or (candidates and "PERF-02" not in candidates):
        raise ValueError("approved_candidates is not a canonical field subset")
    if type(payload["field_complete"]) is not bool or payload["field_complete"] != (
        candidates == list(stories)
    ):
        raise ValueError("field_complete disagrees with approved_candidates")
except (IndexError, KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
    print(f"field capture JSON contract error: {exc}", file=sys.stderr)
    raise SystemExit(2)

sys.stdout.write("\t".join(candidates))
PY
    )"; then
