# ── 17 ───────────────────────────────────────────────────────────────────
stage "#19 への記録と、後続イシューの処理"
say "受け入れ結果を記録します。否・欠損・証拠未移送の項目は閉じず、残作業として残します。"
say ""
note "単一台帳へのレビュー反映: $F_TRACKER_UPDATED"
note "story_trackerのfull/browser/soak/auditは、現行source・manifest・review receiptを再監査できる間、field合格を保持します。新しい明示的失敗は不合格を優先します。"
say ""
ask F_REMOTE_REVIEW "レポートと証拠をcommit/push済み、または権限付き添付URLへ置換済みで、#19のレビュアーが開ける？ (可 / ローカル限定):"
write_env F_REMOTE_REVIEW "$F_REMOTE_REVIEW"
if [[ "$F_REMOTE_REVIEW" != "可" ]]; then
  warn "repo相対pathは手元PCだけでは遠隔から開けないため、#19への自動投稿を止めます。"
  SKIPPED+=("レポートと証拠をcommit/pushするか権限付き添付へ置き、遠隔レビュー可能にしてから #19 へ投稿する")
elif confirm "レポートを #19 にコメントとして投稿しますか？"; then
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if (cd "$LB_ROOT" && gh issue comment 19 -F "$REPORT" >/dev/null 2>&1); then
      printf '  %s✓ 投稿%s #19 にコメントしました\n' "$GREEN" "$RESET"
    else
      warn "gh の投稿に失敗しました"
      SKIPPED+=("#19 へレポートを貼る: gh issue comment 19 -F $REPORT")
    fi
  else
    warn "gh が使えません（未インストール または 未認証）"
    SKIPPED+=("#19 へレポートを貼る: gh issue comment 19 -F $REPORT")
  fi
else
  SKIPPED+=("#19 へレポートを貼る: gh issue comment 19 -F $REPORT")
fi
say ""
if confirm "発見した問題を個別イシューとして起票しますか？"; then
  open_url "$REPO_URL/issues/new"
  note "誤認識サンプル・遅延の詳細・端末固有の不具合は、#19 に埋めず個別イシューへ。"
  pause "起票が終わったら Enter"
else
  SKIPPED+=("発見した問題を個別イシューとして起票する（#19 受け入れ基準の4項目目）")
fi
say ""
note "残りの後続:"
note "  #16 — 前日ステージが通ったなら未消化の2項目が埋まる。手順書の修正を反映してからクローズ判断"
note "  #9  — 実機ベンチ数値を docs/bench に残し、既定エンジンが実機でも妥当かを最終確認"
say ""
if confirm "#16 と #9 を開いて確認しますか？"; then
  open_url "$REPO_URL/issues/16"
  open_url "$REPO_URL/issues/9"
  pause
fi

finish
note "レポート: $REPORT"
note "回答の保存先: $ENV_FILE（再実行すると既定値として復元されます）"
printf '\n'
